$id=trim($_GET['id']??'');$candidate=null;foreach(loadCandidateRecords() as $row)if(($row['id']??'')===$id){$candidate=$row;break;}if(!$candidate){http_response_code(404);exit('Candidate not found.');}$d=candidatePresentation($candidate);$experience=$candidate['experience']??[];$roleKey=fn($v)=>preg_replace('/\s+/',' ',preg_replace('/^sr\.?\s+/','senior ',mb_strtolower(trim((string)$v))));$stmt=db()->prepare('SELECT id,name,required_skills_json FROM wishlist_profiles WHERE user_id=? ORDER BY name');$stmt->execute([currentUser()['id']]);$profiles=array_values(array_filter($stmt->fetchAll(),fn($p)=>$roleKey($p['name'])===$roleKey($d['role'])));$profile=$profiles[0]??null;$required=$profile?(json_decode($profile['required_skills_json']??'[]',true)?:[]):[];$match=profileSkillMatch($candidate,$required);$skillValues=array_values($experience['skill_months']??[]);$maxSkill=$skillValues?max($skillValues):1;
