<section class="detail-grid"><article class="panel detail-panel"><h2>Matched required skills</h2><?php if(!$match['configured']):?><p class="muted">Configure required skills in this job profile first.</p><?php endif?><div class="pills"><?php foreach($match['matched'] as $skill):?><span class="pill"><?=htmlspecialchars($skill)?></span><?php endforeach?></div></article><article class="panel detail-panel"><h2>Missing required skills</h2><div class="pills"><?php foreach($match['missing'] as $skill):?><span class="pill missing"><?=htmlspecialchars($skill)?></span><?php endforeach?></div></article><article class="panel detail-panel"><h2>Key benefits (not scored)</h2><p class="muted">Additional detected skills are useful context but never increase the match score.</p><div class="pills"><?php foreach(array_slice($match['benefits'],0,16) as $skill):?><span class="pill benefit"><?=htmlspecialchars($skill)?></span><?php endforeach?></div></article><article class="panel detail-panel"><h2>Experience timeline</h2><div class="timeline"><?php foreach($experience['jobs']??[] as $job):?><div class="event"><strong><?=htmlspecialchars(($job['start']??'Unknown').' — '.($job['end']??'Unknown'))?></strong><span class="muted"><?=round(($job['months']??0)/12,1)?> years · <?=htmlspecialchars(implode(', ',$job['skills']??[]))?></span></div><?php endforeach?><?php if(empty($experience['jobs'])):?><p class="muted">No reliable dated roles detected.</p><?php endif?></div></article><article class="panel detail-panel"><h2>Skill-wise experience</h2><?php foreach($experience['skill_months']??[] as $skill=>$months):?><div class="skill-row"><span><?=htmlspecialchars($skill)?></span><div class="bar"><i style="width:<?=round($months/$maxSkill*100)?>%"></i></div><b><?=round($months/12,1)?>y</b></div><?php endforeach?></article><article class="panel detail-panel"><h2>Employment gaps</h2><?php foreach($experience['gaps']??[] as $gap):?><div class="event"><strong><?=$gap['months']?> months</strong><span clas